	gemmSmall                   // 64x64, for the narrow heads
)

var gemmVariants = map[gemmKernel]struct {
	spirv  []byte
	bm, bn int
}{
	gemmBig:   {shaders.DiTGEMMWG128x256TiledSWZ8, 128, 256},
	gemmSmall: {shaders.DiTGEMMReg64Tiled, 64, 64},
}

