// Destroy releases every Vulkan object.
func (g *GPU) Destroy() {
	for _, p := range g.pipes {
		p.Destroy()
	}
	for _, p := range g.attnPipes {
		p.Destroy()
	}
	for _, m := range g.gemms {
		for _, p := range m {
			p.Destroy()
		}
	}
	for _, p := range g.dequant {
		p.Destroy()
	}
	for _, m := range g.mods {
		m.Destroy()
	}
	for _, b := range append(append([]*vk.Buffer{g.hbuf, g.abuf, g.wbuf}, g.banks...), g.qbanks...) {
		if b != nil {
			b.Destroy()
		}
	}
}

