#include "dit_common.glsl"

layout(binding = 2) buffer HAct { float16_t hact[]; };

// IN_F16 reads the two halves out of the fp16 arena instead, which is what
// dit_gemm.comp's C_F16 build writes: the same 4096x10240 tensors at half the
// bytes. Their peaks are 250 and 508 against fp16's 65504, so the narrowing
// costs precision and not range (IDEAS §2.6).
#ifndef IN_F16
#define IN_F16 0
#endif
#if IN_F16
#define GATE(i) float(hact[gate + (i)])
#define UP(i)   float(hact[up + (i)])
#else
#define GATE(i) act[gate + (i)]
#define UP(i)   act[up + (i)]
#endif

layout(local_size_x = 256) in;

void main() {
    uint r = gl_WorkGroupID.x;
    if (r >= pc.tokens) {
        return;
    }
    uint gate = pc.inOff + r * pc.dim;
    uint up = pc.kOff + r * pc.dim;
    uint dst = pc.outOff + r * pc.lda;
    float s = uintBitsToFloat(pc.scale);
    for (uint c = gl_LocalInvocationID.x; c < pc.dim; c += 256u) {
        float g = GATE(c);
        hact[dst + c] = float16_t(g / (1.0 + exp(-g)) * UP(c) * s);
    }
}

//go:embed h3enc_conv_oc32.spv
var H3EncConvOC32 []byte

//go:embed h3enc_conv_oc48.spv
var H3EncConvOC48 []byte

//go:embed h3enc_conv_oc16.spv
var H3EncConvOC16 []byte

// TAEQI2.1, Qwen-Image-2.1's preview decoder (qimage/vae/tiny_gpu.go): the
// same convolution with its ReLU and residual add fused into the store. The
// arms are screened by TestTinyKernelScreen; its widths are 256, 128, 64 and
// a 16-channel conv_out, so every block here divides all but the last.

//go:generate glslc --target-env=vulkan1.2 -O -I. -DEPILOGUE -DOC_BLOCK=16u -DIC_BLOCK=8u -o tae_conv_oc16.spv vae_conv2d.comp
