cat > ace/dit/debug2_test.go <<'EOF'
package dit

import (
	"fmt"
	"math"
	"testing"

	"strix-halo-vulkan/safetensors"
	"strix-halo-vulkan/zimage/qwen"
)

func r16(m *qwen.Mat) {
	for i, v := range m.Data {
		m.Data[i] = safetensors.F16ToF32(safetensors.F32ToF16(v))
	}
}

type hostOpts struct{ qk16, ctx16, a16, ff16, p16 bool }

// hostAttn: q [n, H*128], k/v [m, KV*128], GQA, optional window; scores in
// natural units (scale applied here).
func hostAttn(q, k, v *qwen.Mat, heads, kv, win int, p16 bool) *qwen.Mat {
	n, m := q.Rows, k.Rows
	out := qwen.NewMat(n, heads*128)
	scale := 1 / math.Sqrt(128)
	parallel(heads, func(h int) {
		kh := h / (heads / kv)
		s := make([]float64, m)
		for i := 0; i < n; i++ {
			qi := q.Row(i)[h*128 : (h+1)*128]
			mx := math.Inf(-1)
			for j := 0; j < m; j++ {
				if win > 0 && (j < i-win || j > i+win) {
					s[j] = math.Inf(-1)
					continue
				}
				kj := k.Row(j)[kh*128 : (kh+1)*128]
				var d float64
				for c := range qi {
					d += float64(qi[c]) * float64(kj[c])
				}
				s[j] = d * scale
				mx = math.Max(mx, s[j])
			}
			var sum float64
			for j := range s {
				s[j] = math.Exp(s[j] - mx)
				if p16 {
					s[j] = float64(safetensors.F16ToF32(safetensors.F32ToF16(float32(s[j]))))
				}
				sum += s[j]
			}
			o := out.Row(i)[h*128 : (h+1)*128]
			for c := range o {
				var a float64
				for j := 0; j < m; j++ {
					if s[j] != 0 {
						a += s[j] * float64(v.Row(j)[kh*128+c])
					}
				}
				o[c] = float32(a / sum)
			}
		}
	})
	return out
}

func rope(x *qwen.Mat, heads int, theta float64) {
	for p := 0; p < x.Rows; p++ {
		row := x.Row(p)
		for h := 0; h < heads; h++ {
			for j := 0; j < 64; j++ {
				inv := 1 / float32(math.Pow(theta, float64(float32(2*j)/128)))
				a := float64(float32(p) * inv)
				c, s := float32(math.Cos(a)), float32(math.Sin(a))
				x1, x2 := row[h*128+j], row[h*128+j+64]
				row[h*128+j] = x1*c - x2*s
				row[h*128+j+64] = x2*c + x1*s
			}
		}
	}
}

func lin(t *testing.T, l *loader, name string, out, in int) *qwen.Linear {
	w := l.f32(name, out, in)
	if l.err != nil {
		t.Fatal(l.err)
	}
	return &qwen.Linear{Out: out, In: in, Weight: w}
}

func apply(l *qwen.Linear, x *qwen.Mat) *qwen.Mat { y, _ := l.Apply(x); return y }

func hostLayer(t *testing.T, g *GPU, li int, x, enc *qwen.Mat, tt float32, o hostOpts) *qwen.Mat {
	set := mustSet(t)
	defer set.Close()
	l := &loader{set: set}
	p := fmt.Sprintf("decoder.layers.%d.", li)
	H := g.dit.H
	_, proj, _ := g.Host.Timestep(tt)
	tab := g.Host.Tables[li]
	vec := func(j int) []float32 {
		v := make([]float32, H)
		for i := range v {
			v[i] = tab[j*H+i] + proj[j*H+i]
		}
		return v
	}
	mod := func(w []float32, sc, sh []float32) *qwen.Mat {
		n := &qwen.RMSNorm{Weight: w, Eps: g.cfg.Eps}
		y, _ := n.Apply(x)
		for r := 0; r < y.Rows; r++ {
			row := y.Row(r)
			for i := range row {
				row[i] = row[i]*(1+sc[i]) + sh[i]
			}
		}
		if o.a16 {
			r16(y)
		}
		return y
	}
	qn := &qwen.RMSNorm{Weight: l.f32(p+"self_attn.q_norm.weight", 128), Eps: g.cfg.Eps}
	kn := &qwen.RMSNorm{Weight: l.f32(p+"self_attn.k_norm.weight", 128), Eps: g.cfg.Eps}
	a := mod(g.Host.Norms[li][0], vec(1), vec(0))
	q := apply(lin(t, l, p+"self_attn.q_proj.weight", 4096, H), a)
	k := apply(lin(t, l, p+"self_attn.k_proj.weight", 1024, H), a)
	v := apply(lin(t, l, p+"self_attn.v_proj.weight", 1024, H), a)
	qn.ApplyInPlace(q)
	kn.ApplyInPlace(k)
	rope(q, 32, g.cfg.Theta)
	rope(k, 8, g.cfg.Theta)
	if o.qk16 {
		r16(q)
		r16(k)
		r16(v)
	}
	win := 0
	if g.cfg.Windowed(li) {
		win = g.cfg.Window
	}
	ctx := hostAttn(q, k, v, 32, 8, win, o.p16)
	if o.ctx16 {
		r16(ctx)
	}
	so := apply(lin(t, l, p+"self_attn.o_proj.weight", H, 4096), ctx)
	g2 := vec(2)
	for r := 0; r < x.Rows; r++ {
		for i := 0; i < H; i++ {
			x.Data[r*H+i] += so.Data[r*H+i] * g2[i]
		}
	}
	// cross
	cn := &qwen.RMSNorm{Weight: l.f32(p+"cross_attn_norm.weight", H), Eps: g.cfg.Eps}
	ca, _ := cn.Apply(x)
	ce := apply(lin(t, l, "decoder.condition_embedder.weight", H, 2048), enc)
	for r := 0; r < ce.Rows; r++ {
		for i := 0; i < H; i++ {
			ce.Data[r*H+i] += g.Host.CondB[i]
		}
	}
	cq := apply(lin(t, l, p+"cross_attn.q_proj.weight", 4096, H), ca)
	ck := apply(lin(t, l, p+"cross_attn.k_proj.weight", 1024, H), ce)
	cv := apply(lin(t, l, p+"cross_attn.v_proj.weight", 1024, H), ce)
	(&qwen.RMSNorm{Weight: l.f32(p+"cross_attn.q_norm.weight", 128), Eps: g.cfg.Eps}).ApplyInPlace(cq)
	(&qwen.RMSNorm{Weight: l.f32(p+"cross_attn.k_norm.weight", 128), Eps: g.cfg.Eps}).ApplyInPlace(ck)
	cc := hostAttn(cq, ck, cv, 32, 8, 0, false)
	co := apply(lin(t, l, p+"cross_attn.o_proj.weight", H, 4096), cc)
	for i := range x.Data {
		x.Data[i] += co.Data[i]
	}
	f := mod(g.Host.Norms[li][1], vec(4), vec(3))
	gt := apply(lin(t, l, p+"mlp.gate_proj.weight", 9728, H), f)
	up := apply(lin(t, l, p+"mlp.up_proj.weight", 9728, H), f)
	for i, gv := range gt.Data {
		gt.Data[i] = gv / (1 + float32(math.Exp(float64(-gv)))) * up.Data[i]
	}
